#include <stdio.h>

int main() {
    int coins[] = {1, 3, 4};
    int amount = 6;
    int dp[7];
    dp[0] = 0;
    for (int a = 1; a <= amount; a++) {
        dp[a] = 1000;
        for (int c = 0; c < 3; c++) {
            if (coins[c] <= a && dp[a - coins[c]] + 1 < dp[a]) {
                dp[a] = dp[a - coins[c]] + 1;
            }
        }
    }
    printf("Minimum coins for %d: %d\n", amount, dp[amount]);
    return 0;
}
